+  const child = childrenOf(document, name)[0];
+  return Node.isPrimitive(child)
+    ? Option.some(Node.propsOf(child))
+    : Option.none;
+}
+
+function resizeTo(
+  document: DesignDocument,
+  name: string,
+  length: AxisLength,
